import { expect, it } from "vitest";
import { RequestBudget } from "../../src/worker/spotify/client";
import { onboarded } from "./harness";

it("red-team: a stale Next occurrence must not skip the freshly observed successor", async () => {
  const h = await onboarded({ tracks: 60 });
  const id = h.stationIds[0]!;
  await h.hub.play(id);
  await h.hub.sync(new RequestBudget(25), { force: true });
  const before = h.hub.savedSession(id)!;
  const expected = { sessionId: before.sessionId, entryId: before.entryIds[before.currentIndex] };
  const player = h.fake.user().player;
  h.fake.advance(h.fake.tracks.get(player.order[player.index]!)!.durationMs + 1000);
  const calls = h.fake.calls.length;
  const result = await h.hub.playerAction("next", expected);
  console.log(JSON.stringify({ expected, result, before: before.currentIndex, actualPosition: player.index, calls: h.fake.calls.slice(calls) }));
  expect(result.ok).toBe(false);
  expect(h.fake.calls.slice(calls)).not.toContain("POST /v1/me/player/next");
});

it("red-team: applied pause followed by provider 500 is an ambiguous result", async () => {
  const h = await onboarded({ tracks: 60 });
  const id = h.stationIds[0]!;
  await h.hub.play(id);
  await h.hub.sync(new RequestBudget(25), { force: true });
  const handle = h.fake.handle.bind(h.fake);
  h.fake.handle = async (req) => {
    const response = await handle(req);
    if (req.method === "PUT" && new URL(req.url).pathname === "/v1/me/player/pause")
      return Response.json({ error: { status: 500, message: "response interrupted" } }, { status: 500 });
    return response;
  };
  const result = await h.hub.playerAction("pause");
  console.log(JSON.stringify({ result, actualPlaying: h.fake.user().player.isPlaying, sessionStatus: h.hub.savedSession(id)?.status }));
  expect(result).toMatchObject({ ok: false, uncertain: true, error: { code: "unknown" } });
  expect(h.fake.user().player.isPlaying).toBe(false);
});

