import { expect, it } from "vitest";
import { onboarded } from "./harness";
import { RequestBudget } from "../../src/worker/spotify/client";

it("red-team: definitely unexecuted Next must release its intent after token refresh fails", async () => {
  const h = await onboarded({ tracks: 60 });
  const id = h.stationIds[0]!;
  await h.hub.play(id);
  await h.hub.sync(new RequestBudget(25), { force: true });
  const before = h.hub.savedSession(id)!;
  const handle = h.fake.handle.bind(h.fake);
  let rejectedWrites = 0;
  h.fake.handle = async req => {
    const path = new URL(req.url).pathname;
    if (path === "/accounts/api/token") throw new Error("token refresh unavailable");
    if (path === "/v1/me/player/next") {
      rejectedWrites++;
      return Response.json({error: {status: 401, message: "expired access token"}}, {status: 401});
    }
    return handle(req);
  };
  const result = await h.hub.playerAction("next", {sessionId: before.sessionId, entryId: before.entryIds[before.currentIndex]});
  console.log(JSON.stringify({result, rejectedWrites, pending: h.hub.savedSession(id)?.pending}));
  expect(result.uncertain).toBeUndefined();
  expect(rejectedWrites).toBe(1);
  expect(h.hub.savedSession(id)?.pending).toBeNull();
});

