import { expect, it } from "vitest";
import { RequestBudget } from "../../src/worker/spotify/client";
import { onboarded } from "./harness";

const kv = (h: Awaited<ReturnType<typeof onboarded>>, key: string) => {
  const row = h.sql.first<{ v: string }>("SELECT v FROM kv WHERE k = ?", key);
  return row ? JSON.parse(row.v) : null;
};

it("red-team: maintenance wakes and eviction cannot postpone a long-paused player deadline", async () => {
  const h = await onboarded({ tracks: 60 });
  const id = h.stationIds[0]!;
  await h.hub.play(id);
  h.fake.user().player.progressMs = 97000;
  await h.hub.sync(new RequestBudget(25), { force: true });
  await h.hub.playerAction("pause");
  await h.listen(4 * 60 * 60 * 1000);
  await h.hub.sync(new RequestBudget(25), { force: true });
  const before = h.hub.savedSession(id)!;
  const start = h.fake.calls.length;
  const checkedAt = kv(h, "player_checked_at");
  for (let tick = 1; tick < 60; tick++) {
    h.clock.t += 15000;
    if (tick === 30) h.restart();
    await h.hub.alarm();
  }
  expect(h.fake.calls.slice(start).filter(c => c === "GET /v1/me/player")).toHaveLength(0);
  expect(kv(h, "player_checked_at")).toBe(checkedAt);
  h.clock.t += 15000;
  await h.hub.alarm();
  expect(h.fake.calls.slice(start).filter(c => c === "GET /v1/me/player")).toHaveLength(1);
  expect(h.hub.savedSession(id)).toMatchObject({ sessionId: before.sessionId, currentIndex: before.currentIndex, entryIds: before.entryIds, progressMs: before.progressMs });
});

it("red-team: failed player reads cannot update success freshness or cause rapid retries", async () => {
  const h = await onboarded({ tracks: 60 });
  await h.hub.play(h.stationIds[0]!);
  await h.hub.playerAction("pause");
  await h.listen(1000);
  const checkedAt = kv(h, "player_checked_at");
  const handle = h.fake.handle.bind(h.fake);
  let attempts = 0;
  h.fake.handle = async req => {
    if (req.method === "GET" && new URL(req.url).pathname === "/v1/me/player") {
      attempts++;
      return Response.json({ error: { status: 500, message: "unavailable" } }, { status: 500 });
    }
    return handle(req);
  };
  h.clock.t += 6000;
  await h.hub.sync(new RequestBudget(25), { force: true });
  for (let second = 0; second < 14; second++) {
    h.clock.t += 1000;
    if (second === 7) h.restart();
    await h.hub.state({ live: true, refresh: true });
    await h.hub.alarm();
  }
  expect(attempts).toBe(2); // The existing read transport has one bounded retry.
  expect(kv(h, "player_checked_at")).toBe(checkedAt);
  h.clock.t += 1000;
  await h.hub.alarm();
  expect(attempts).toBe(4);
  expect(kv(h, "player_checked_at")).toBe(checkedAt);
});

