/** Rendered client races use intercepted API snapshots; no provider or history writes. */
import { expect, type Page, type Route, test } from "@playwright/test";
import { DEFAULT_RULES } from "../src/core/types";
import type { AppState, DeviceView } from "../src/shared/api";

test.use({ viewport: { width: 390, height: 844 } });

const TIME = Date.UTC(2026, 9, 1, 12);
const tracks = ["Erster Song", "Zweiter Song", "Dritter Song"].map((name, index) => ({
	id: `track-${index}`,
	name,
	artists: "Test Artist",
	album: "Test Album",
	imageUrl: null,
	durationMs: 60_000,
	thumb: 0 as const,
}));
function snapshot(playing = true): AppState {
	return {
		profile: { id: "listener-a", name: "Test Listener", imageUrl: null },
		onboarded: true,
		stations: [
			{
				id: 1,
				name: "Test Sender",
				kind: "all",
				sources: [],
				rules: DEFAULT_RULES,
				roundNo: 1,
				poolSize: 3,
				freshRemaining: 3,
				progress: 0,
				playlistId: null,
				ready: true,
				importing: false,
				lastPlayedAt: TIME,
				playing,
				imageUrl: null,
			},
		],
		session: {
			sessionId: "session-a",
			stationId: 1,
			entryId: "entry-0",
			orderRevision: 1,
			progressMs: 12_000,
			observedAt: TIME,
			status: playing ? "active" : "paused",
			pending: false,
			queue: tracks.map((track, index) => ({ entryId: `entry-${index}`, track })),
		},
		nowPlaying: {
			...tracks[0]!,
			isPlaying: playing,
			progressMs: 12_000,
			stationId: 1,
			kind: "fresh",
			deviceName: "Test iPhone",
			orderBroken: false,
			smartShuffle: false,
			observedAt: TIME,
		},
		guest: { active: false, until: null },
		warnings: [],
		jobs: [],
		history: { importedTracks: 0, importedAt: null, liveSince: TIME },
		aiSource: "off",
		serverTime: TIME,
	};
}
function deferred() {
	let release = () => {};
	const promise = new Promise<void>((resolve) => {
		release = resolve;
	});
	return { promise, release };
}
async function setup(page: Page, initial = snapshot()) {
	const model = {
		state: initial,
		stateCalls: 0,
		stateQueries: [] as string[],
		requests: [] as string[],
		devices: [
			{ id: "iphone", name: "Test iPhone", active: true, restricted: false, type: "Smartphone" },
		] as DeviceView[],
		stateHandler: null as ((route: Route) => Promise<void>) | null,
	};
	await page.clock.install({ time: TIME });
	await page.clock.setFixedTime(TIME);
	await page.route("**/api/**", async (route) => {
		const path = new URL(route.request().url()).pathname;
		model.requests.push(path);
		if (path === "/api/state") {
			model.stateCalls++;
			model.stateQueries.push(new URL(route.request().url()).search);
			if (model.stateHandler) return model.stateHandler(route);
			return route.fulfill({ json: model.state });
		}
		if (path === "/api/devices") return route.fulfill({ json: model.devices });
		if (path === "/api/native/devices")
			return route.fulfill({ json: { configured: false, devices: [] } });
		return route.fulfill({
			status: 500,
			json: { error: { code: "unexpected", message: `Unexpected ${path}` } },
		});
	});
	await page.goto("/");
	await expect(page.locator(".now-copy h2")).toHaveText("Erster Song");
	await expect(
		page.locator(".device-select select option", { hasText: "Test iPhone" }),
	).toHaveCount(1);
	expect(
		await page.evaluate(() => document.documentElement.scrollWidth - innerWidth),
	).toBeLessThanOrEqual(0);
	return model;
}
async function advance(page: Page, milliseconds: number) {
	const now = await page.evaluate(() => Date.now());
	await page.clock.setFixedTime(now + milliseconds);
	await page.clock.runFor(milliseconds);
}
async function refresh(page: Page) {
	const response = page.waitForResponse((r) => new URL(r.url()).pathname === "/api/state");
	await page.evaluate(() => window.dispatchEvent(new Event("focus")));
	await response;
}
function observe(
	model: { state: AppState },
	patch: Partial<NonNullable<AppState["session"]>>,
	at: number,
) {
	Object.assign(model.state.session!, patch, { observedAt: at });
	model.state.serverTime = at;
	if (model.state.nowPlaying)
		Object.assign(model.state.nowPlaying, {
			observedAt: at,
			progressMs: patch.progressMs ?? model.state.nowPlaying.progressMs,
		});
}

test("red-team: ambiguous provider write must remain unconfirmed", async ({ page }) => {
  await setup(page);
  await page.route("**/api/player/pause", async route => route.fulfill({ json: { ok: false, uncertain: true, error: { code: "unknown", message: "Spotify meldet: Spotify-Fehler 500" } } }));
  await page.getByRole("button", { name: "Pause", exact: true }).click();
  await expect(page.locator(".session-status")).toHaveText("Bestätigung steht aus");
});

test("red-team: repeated cached snapshots cannot restart the projection age", async ({ page }) => {
  const initial = snapshot();
  initial.session!.progressMs = 59000;
  initial.nowPlaying!.progressMs = 59000;
  const model = await setup(page, initial);
  await advance(page, 2000);
  await expect(page.locator(".now-copy h2")).toHaveText("Zweiter Song");
  for (let i = 1; i <= 9; i++) {
    await advance(page, 15000);
    model.state.serverTime = TIME + 2000 + i * 15000;
    await refresh(page);
  }
  await expect(page.locator(".now-copy h2")).toHaveText("Erster Song");
  await expect(page.locator(".session-status")).toHaveText("Gerätebestätigung steht aus");
  await expect(page.getByRole("button", { name: "Weiter: Nächster Song" })).toBeDisabled();
});

test("red-team: an accepted pause cannot be confirmed by a newer envelope with an old observation", async ({ page }) => {
  const model = await setup(page);
  await page.route("**/api/player/pause", async route => route.fulfill({ json: { ok: true, acceptedAt: TIME + 1000 } }));
  await page.getByRole("button", { name: "Pause", exact: true }).click();
  model.state.serverTime = TIME + 2000;
  model.state.session!.status = "paused";
  model.state.nowPlaying!.isPlaying = false;
  await refresh(page);
  await expect(page.getByText("Befehl angenommen.", { exact: false })).toBeVisible();
  await expect(page.locator(".session-status")).not.toHaveText("Pausiert");
});

 test("red-team: another tab must not report acknowledged pause as device-confirmed", async ({ page }) => {
 const initial = snapshot();
 initial.session!.status = "paused";
 await setup(page, initial);
 await expect(page.locator(".session-status")).toHaveText("Gerätebestätigung steht aus");
 });

test("red-team: a vanished device after accepted pause retains a manual saved resume", async ({ page }) => {
 const model = await setup(page);
 await page.route("**/api/player/pause", async route => route.fulfill({ json: { ok: true, acceptedAt: TIME + 1000 } }));
 await page.getByRole("button", { name: "Pause", exact: true }).click();
 model.state.serverTime = TIME + 2000;
 model.state.session!.status = "disconnected";
 model.state.nowPlaying = null;
 await refresh(page);
 await advance(page, 21000);
 await expect(page.locator(".session-status")).toHaveText("Bestätigung steht aus");
 await expect.soft(page.getByLabel("Wiedergabegerät", { exact: true })).toBeEnabled({ timeout: 1000 });
 const recover = page.getByRole("button", { name: /Gespeicherten Song.*fortsetzen/ });
 await expect.soft(recover).toBeVisible({ timeout: 1000 });
 let sent: unknown;
 await page.route("**/api/stations/1/play", async route => {
   sent = route.request().postDataJSON();
   await route.fulfill({ json: { ok: true, acceptedAt: TIME + 23000 } });
 });
 await page.getByLabel("Wiedergabegerät", { exact: true }).selectOption("iphone");
 await recover.click();
 await expect.poll(() => sent).toEqual({ deviceId: "iphone", newQueue: false, sessionId: "session-a" });
});

test("red-team: confirmed native pause is independent of cached Spotify playback", async ({ page }) => {
 const initial = snapshot(false);
 initial.nowPlaying!.isPlaying = true;
 initial.session!.controller = {kind: "home-assistant", deviceId: "living-room", deviceName: "Wohnzimmer"};
 await setup(page, initial);
 await expect(page.locator(".session-status")).toHaveText("Pausiert");
});


test("red-team: accepted start retains bounded confirmation reads after station navigation", async ({ page }) => {
  const model = await setup(page, snapshot(false));
  const detail = { ...model.state.stations[0], upcoming: [], recent: [], counts: null, discoveries: { pending: 0, kept: 0, rejected: 0 } };
  await page.route("**/api/stations/1", route => route.fulfill({ json: detail }));
  await page.route("**/api/stations/1/play", route => route.fulfill({ json: { ok: true, acceptedAt: TIME + 1000 } }));
  await page.getByRole("button", { name: "Fortsetzen", exact: true }).click();
  await expect(page.locator(".session-status")).toHaveText("Start angefordert …");
  await expect.poll(() => model.stateCalls).toBeGreaterThan(1);
  await page.getByRole("link", { name: "Test Sender: Mix und Regeln" }).click();
  await expect(page.getByRole("heading", { name: "Test Sender", level: 1 })).toBeVisible();
  model.state = snapshot(true);
  observe(model, { status: "active", progressMs: 13000 }, TIME + 2000);
  await advance(page, 4500);
  await expect(page.getByRole("heading", { name: "Läuft gerade", exact: true })).toBeVisible({ timeout: 1000 });
});

